import{_ as i,a0 as l,w as o,s as r,I as a,x as n,a1 as e,A as t,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const q=JSON.parse('{"title":"使用 RT-Thread 的 FinSH 对硬件进行编程 | LCTT x X-CMD","titleTemplate":false,"description":"使用 RT-Thread 的 FinSH 对硬件进行编程 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 RT-Thread 的 FinSH 对硬件进行编程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 RT-Thread 的 FinSH 对硬件进行编程 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200907 Program hardware from the Linux command line","title":"使用 RT-Thread 的 FinSH 对硬件进行编程","tag":"202009","desc":""},"relativePath":"202009/20200907 Program hardware from the Linux command line.md","filePath":"[post].md"}'),c={name:"202009/20200907 Program hardware from the Linux command line.md"};function u(h,s,g,k,m,f){const p=l("Link");return o(),r("div",null,[s[20]||(s[20]=a("h1",{id:"使用-rt-thread-的-finsh-对硬件进行编程",tabindex:"-1"},[n("使用 RT-Thread 的 FinSH 对硬件进行编程 "),a("a",{class:"header-anchor",href:"#使用-rt-thread-的-finsh-对硬件进行编程","aria-label":"Permalink to “使用 RT-Thread 的 FinSH 对硬件进行编程”"},"​")],-1)),s[21]||(s[21]=a("blockquote",null,[a("p",null,"由于物联网（IoT）的兴起，对硬件进行编程变得越来越普遍。RT-Thread 可以让你可以用 FinSH 从 Linux 命令行与设备进行沟通、")],-1)),s[22]||(s[22]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202009/29/233059w523g55qzvo53h6i.jpg",alt:""})],-1)),a("p",null,[s[2]||(s[2]=n("RT-Thread 是一个开源的",-1)),e(p,{href:"https://opensource.com/article/20/6/open-source-rtos"},{default:t(()=>[...s[0]||(s[0]=[n("实时操作系统",-1)])]),_:1}),s[3]||(s[3]=n("，用于对物联网（IoT）设备进行编程。FinSH 是 ",-1)),e(p,{href:"https://github.com/RT-Thread/rt-thread"},{default:t(()=>[...s[1]||(s[1]=[n("RT-Thread",-1)])]),_:1}),s[4]||(s[4]=n(" 的命令行组件，它提供了一套操作界面，使用户可以从命令行与设备进行沟通。它主要用于调试或查看系统信息。",-1))]),s[23]||(s[23]=d(`<p>通常情况下，开发调试使用硬件调试器和 <code>printf</code> 日志来显示。但在某些情况下，这两种方法并不是很有用，因为它是从运行的内容中抽象出来的，而且它们可能很难解析。不过 RT-Thread 是一个多线程系统，当你想知道一个正在运行的线程的状态，或者手动控制系统的当前状态时，这很有帮助。因为它是多线程的，所以你能够拥有一个交互式的 shell，你可以直接在设备上输入命令、调用函数来获取你需要的信息，或者控制程序的行为。如果你只习惯于 Linux 或 BSD 等现代操作系统，这在你看来可能很普通，但对于硬件黑客来说，这是极其奢侈的，远超将串行电缆直接连线到电路板上以获取一丝错误的做法。</p><p>FinSH 有两种模式。</p><ul><li>C 语言解释器模式，称为 c-style。</li><li>传统的命令行模式，称为 msh（模块 shell）。</li></ul><p>在 C 语言解释器模式下，FinSH 可以解析执行大部分 C 语言的表达式，并使用函数调用访问系统上的函数和全局变量。它还可以从命令行创建变量。</p><p>在 msh 模式下，FinSH 的操作与 Bash 等传统 shell 类似。</p><h3 id="gnu-命令标准" tabindex="-1">GNU 命令标准 <a class="header-anchor" href="#gnu-命令标准" aria-label="Permalink to “GNU 命令标准”">​</a></h3><p>当我们在开发 FinSH 时，我们了解到，在编写命令行应用程序之前，你需要熟悉 GNU 命令行标准。这个标准实践的框架有助于给界面带入熟悉感，这有助于开发人员在使用时感到舒适和高效。</p><p>一个完整的 GNU 命令主要由四个部分组成。</p><ol><li>命令名（可执行文件）：命令行程序的名称；</li><li>子命令：命令程序的子函数名称。</li><li>选项：子命令函数的配置选项。</li><li>参数：子命令函数配置选项的相应参数。</li></ol><p>你可以在任何命令中看到这一点。以 Git 为例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git reset --hard HEAD~1</span></span></code></pre></div><p>这一点可以分解为：</p><p><img src="https://opensource.com/sites/default/files/uploads/command-line-apps_2.png" alt="GNU command line standards" title="GNU command line standards"></p><p>可执行的命令是 <code>git</code>，子命令是 <code>reset</code>，使用的选项是 <code>--head</code>，参数是 <code>HEAD~1</code>。</p><p>再举个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl enable --now firewalld</span></span></code></pre></div><p>可执行的命令是 <code>systemctl</code>，子命令是 <code>enable</code>，选项是 <code>--now</code>，参数是 <code>firewalld</code>。</p><p>想象一下，你想用 RT-Thread 编写一个符合 GNU 标准的命令行程序。FinSH 拥有你所需要的一切，并且会按照预期运行你的代码。更棒的是，你可以依靠这种合规性，让你可以自信地移植你最喜欢的 Linux 程序。</p><h3 id="编写一个优雅的命令行程序" tabindex="-1">编写一个优雅的命令行程序 <a class="header-anchor" href="#编写一个优雅的命令行程序" aria-label="Permalink to “编写一个优雅的命令行程序”">​</a></h3><p>下面是一个 RT-Thread 运行命令的例子，RT-Thread 开发人员每天都在使用这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>usage: env.py package [-h] [--force-update] [--update] [--list] [--wizard]</span></span>
<span class="line"><span>                      [--upgrade] [--printenv]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>optional arguments:</span></span>
<span class="line"><span>  -h, --help      show this help message and exit</span></span>
<span class="line"><span>  --force-update  force update and clean packages, install or remove the</span></span>
<span class="line"><span>                  packages by your settings in menuconfig</span></span>
<span class="line"><span>  --update        update packages, install or remove the packages by your</span></span>
<span class="line"><span>                  settings in menuconfig</span></span>
<span class="line"><span>  --list          list target packages</span></span>
<span class="line"><span>  --wizard        create a new package with wizard</span></span>
<span class="line"><span>  --upgrade       upgrade local packages list and ENV scripts from git repo</span></span>
<span class="line"><span>  --printenv      print environmental variables to check</span></span></code></pre></div><p>正如你所看到的那样，它看起来很熟悉，行为就像你可能已经在 Linux 或 BSD 上运行的大多数 POSIX 应用程序一样。当使用不正确或不充分的语法时，它会提供帮助，它支持长选项和短选项。这种通用的用户界面对于任何使用过 Unix 终端的人来说都是熟悉的。</p><h3 id="选项种类" tabindex="-1">选项种类 <a class="header-anchor" href="#选项种类" aria-label="Permalink to “选项种类”">​</a></h3><p>选项的种类很多，按长短可分为两大类。</p><ol><li>短选项：由一个连字符加一个字母组成，如 <code>pkgs -h</code> 中的 <code>-h</code> 选项。</li><li>长选项：由两个连字符加上单词或字母组成，例如，<code>scons- --target-mdk5</code> 中的 <code>--target</code> 选项。</li></ol><p>你可以把这些选项分为三类，由它们是否有参数来决定。</p><ol><li>没有参数：该选项后面不能有参数。</li><li>参数必选：选项后面必须有参数。</li><li>参数可选：选项后可以有参数，但不是必需的。</li></ol><p>正如你对大多数 Linux 命令的期望，FinSH 的选项解析非常灵活。它可以根据空格或等号作为定界符来区分一个选项和一个参数，或者仅仅通过提取选项本身并假设后面的内容是参数（换句话说，完全没有定界符）。</p><ul><li><code>wavplay -v 50</code></li><li><code>wavplay -v50</code></li><li><code>wavplay --vol=50</code></li></ul><h3 id="使用-optparse" tabindex="-1">使用 optparse <a class="header-anchor" href="#使用-optparse" aria-label="Permalink to “使用 optparse”">​</a></h3><p>如果你曾经写过命令行程序，你可能会知道，一般来说，你所选择的语言有一个叫做 optparse 的库或模块。它是提供给程序员的，所以作为命令的一部分输入的选项（比如 <code>-v</code> 或 <code>--verbose</code>）可以与命令的其他部分进行<em>解析</em>。这可以帮助你的代码从一个子命令或参数中获取一个选项。</p><p>当为 FinSH 编写一个命令时，<code>optparse</code> 包希望使用这种格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MSH_CMD_EXPORT_ALIAS(pkgs, pkgs, this is test cmd.);</span></span></code></pre></div><p>你可以使用长形式或短形式，或者同时使用两种形式来实现选项。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>static struct optparse_long long_opts[] =</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    {&quot;help&quot;        , &#39;h&#39;, OPTPARSE_NONE}, // Long command: help, corresponding to short command h, without arguments.</span></span>
<span class="line"><span>    {&quot;force-update&quot;,  0 , OPTPARSE_NONE}, // Long comman: force-update, without arguments</span></span>
<span class="line"><span>    {&quot;update&quot;      ,  0 , OPTPARSE_NONE},</span></span>
<span class="line"><span>    {&quot;list&quot;        ,  0 , OPTPARSE_NONE},</span></span>
<span class="line"><span>    {&quot;wizard&quot;      ,  0 , OPTPARSE_NONE},</span></span>
<span class="line"><span>    {&quot;upgrade&quot;     ,  0 , OPTPARSE_NONE},</span></span>
<span class="line"><span>    {&quot;printenv&quot;    ,  0 , OPTPARSE_NONE},</span></span>
<span class="line"><span>    { NULL         ,  0 , OPTPARSE_NONE}</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>创建完选项后，写出每个选项及其参数的命令和说明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>static void usage(void)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    rt_kprintf(&quot;usage: env.py package [-h] [--force-update] [--update] [--list] [--wizard]\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;                      [--upgrade] [--printenv]\\n\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;optional arguments:\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  -h, --help      show this help message and exit\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --force-update  force update and clean packages, install or remove the\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;                  packages by your settings in menuconfig\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --update        update packages, install or remove the packages by your\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;                  settings in menuconfig\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --list          list target packages\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --wizard        create a new package with wizard\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --upgrade       upgrade local packages list and ENV scripts from git repo\\n&quot;);</span></span>
<span class="line"><span>    rt_kprintf(&quot;  --printenv      print environmental variables to check\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>下一步是解析。虽然你还没有实现它的功能，但解析后的代码框架是一样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int pkgs(int argc, char **argv)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    int ch;</span></span>
<span class="line"><span>    int option_index;</span></span>
<span class="line"><span>    struct optparse options;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if(argc == 1)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        usage();</span></span>
<span class="line"><span>        return RT_EOK;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    optparse_init(&amp;options, argv);</span></span>
<span class="line"><span>    while((ch = optparse_long(&amp;options, long_opts, &amp;option_index)) != -1)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        ch = ch;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        rt_kprintf(&quot;\\n&quot;);</span></span>
<span class="line"><span>        rt_kprintf(&quot;optopt = %c\\n&quot;, options.optopt);</span></span>
<span class="line"><span>        rt_kprintf(&quot;optarg = %s\\n&quot;, options.optarg);</span></span>
<span class="line"><span>        rt_kprintf(&quot;optind = %d\\n&quot;, options.optind);</span></span>
<span class="line"><span>        rt_kprintf(&quot;option_index = %d\\n&quot;, option_index);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    rt_kprintf(&quot;\\n&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    return RT_EOK;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里是函数头文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &quot;optparse.h&quot;</span></span>
<span class="line"><span>#include &quot;finsh.h&quot;</span></span></code></pre></div><p>然后，编译并下载到设备上。</p><p><img src="https://opensource.com/sites/default/files/uploads/command-line-apps_3.png" alt="Output" title="Output"></p><h3 id="硬件黑客" tabindex="-1">硬件黑客 <a class="header-anchor" href="#硬件黑客" aria-label="Permalink to “硬件黑客”">​</a></h3><p>对硬件进行编程似乎很吓人，但随着物联网的发展，它变得越来越普遍。并不是所有的东西都可以或者应该在树莓派上运行，但在 RT-Thread，FinSH 可以让你保持熟悉的 Linux 感觉。</p><p>如果你对在裸机上编码感到好奇，不妨试试 RT-Thread。</p><hr>`,47)),a("p",null,[s[6]||(s[6]=n("via: ",-1)),e(p,{href:"https://opensource.com/article/20/9/hardware-command-line"},{default:t(()=>[...s[5]||(s[5]=[n("https://opensource.com/article/20/9/hardware-command-line",-1)])]),_:1})]),a("p",null,[s[11]||(s[11]=n("作者：",-1)),e(p,{href:"https://opensource.com/users/alansmithee"},{default:t(()=>[...s[7]||(s[7]=[n("Alan Smithee",-1)])]),_:1}),s[12]||(s[12]=n(" 选题：",-1)),e(p,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[n("lujun9972",-1)])]),_:1}),s[13]||(s[13]=n(" 译者：",-1)),e(p,{href:"https://github.com/wxy"},{default:t(()=>[...s[9]||(s[9]=[n("wxy",-1)])]),_:1}),s[14]||(s[14]=n(" 校对：",-1)),e(p,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原创编译，",-1)),e(p,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[n("Linux中国",-1)])]),_:1}),s[19]||(s[19]=n(" 荣誉推出",-1))])])}const v=i(c,[["render",u]]);export{q as __pageData,v as default};
